import django.db.models.deletion
from django.db import migrations, models
from django.utils import timezone


def seed_snapshot_accounts(apps, schema_editor):
    balance_model = apps.get_model("leave", "LeaveBalance")
    account_model = apps.get_model("leave", "LeaveYearAccount")
    ledger_model = apps.get_model("leave", "LeaveLedgerEntry")
    from django.db.models import Sum

    year = timezone.localdate().year
    # LeaveBalance is a legacy point-in-time snapshot. Preserve it once as the
    # opening balance; historical ledger rows remain untouched and are not replayed.
    for row in balance_model.objects.all().iterator():
        consumed = (
            ledger_model.objects.filter(
                employee_id=row.employee_id,
                leave_type=row.leave_type,
                kind__in=("debit", "adjustment"),
                request__start_date__year=year,
            ).aggregate(total=Sum("amount"))["total"]
            or 0
        )
        opening = row.balance + consumed
        account_model.objects.get_or_create(
            employee_id=row.employee_id,
            leave_type=row.leave_type,
            year=year,
            defaults={
                "opening_balance": opening,
                "available_balance": opening,
                "source": "legacy_snapshot",
            },
        )


